function baseFresh(){return {achievements:initialAchievements(),chartBook:initialChartBook(),finance:initialFinance(),careerRecords:{sinceWeek:1,tours:[],openMics:0,royalties:0,liveGross:0,liveProfit:0},developmentVersion:1,development:initialDevelopment(),pacingVersion:1,chartRulesVersion:2,chartWeek:1,name:'Solace',genre:'Hip-hop',background:'Bedroom artist',week:1,cash:650,fans:42,energy:200,energyVersion:2,skill:0,reputation:8,stage:0,loyalty:20,ap:6,songs:[],albums:[],draft:null,boost:0,streams:0,total:0,started:false,world:makeWorld(),feed:[],history:[{week:1,text:'Your story starts here. 200 energy. One first impression.'}]}}
let saveReady=false,saveBusy=false,saveConflict=false,saveTimer,lastSaved='',saveEtag=null;
let s=fresh(),tab='Home',careerTab='Profile',industryTab='Artists',chartKind='Songs',chartMine=false,certificateFilter='Songs',achievementFilter='All',filter='All',genreFilter='All';
